1	package main
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// 本文件实现阶梯客户的按月暂停区间：登记（customer suspend）与查询
11	// （customer suspensions）。区间按 UTC 自然月解释为 [起月, 结束月)，
12	// 包含起月、不包含结束月；暂停月不接收用量、不产生月费账单。区间可相接
13	// （相接视为连续暂停）但不得重叠，不在任何区间内的月份正常服务。记录一旦
14	// 写入永不修改或删除；暂停不产生账后流水事件，也不占用全局操作序号。
15	// 固定单价客户不适用暂停。
16	
17	func cmdCustomerSuspend(dir, customerID, startMonth, endMonth, reason string) error {
18		if !validMonth(startMonth) {
19			return fmt.Errorf("暂停起月 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", startMonth)
20		}
21		if !validMonth(endMonth) {
22			return fmt.Errorf("暂停结束月 %q 无效，必须是 YYYY-MM 形式（如 2027-02）", endMonth)
23		}
24		if endMonth <= startMonth {
25			return fmt.Errorf("暂停结束月 %s 必须晚于起月 %s（区间包含起月、不包含结束月）", endMonth, startMonth)
26		}
27		if strings.TrimSpace(reason) == "" {
28			return fmt.Errorf("暂停原因不能为空")
29		}
30	
31		s, err := loadStore(dir)
32		if err != nil {
33			return err
34		}
35		cust, ok := s.Customers[customerID]
36		if !ok {
37			return fmt.Errorf("客户标识 %q 不存在", customerID)
38		}
39		if cust.PlanID == "" {
40			return fmt.Errorf("客户 %s 是固定单价客户（单价 %d 分），未绑定阶梯方案，不适用暂停", customerID, cust.Price)
41		}
42	
43		key := suspensionKey(customerID, startMonth)
44		if existing, ok := s.Suspensions[key]; ok {
45			// 一项暂停由客户与起月共同标识：相同结束月与原因的重放返回原记录，
46			// 不写盘——即使后来结算了恢复后的月份也须成功；结束月或原因不同
47			// 则拒绝，记录不可改写。
48			if existing.EndMonth == endMonth && existing.Reason == reason {
49				fmt.Fprintf(stdout, "客户 %s 自 %s 起的暂停区间已存在且内容相同，返回原记录（不写盘）：\n\n", customerID, startMonth)
50				printSuspension(existing)
51				return nil
52			}
53			return fmt.Errorf("客户 %s 在 %s 已登记暂停区间（结束月 %s，原因 %q），内容不同，暂停记录不可改写",
54				customerID, startMonth, existing.EndMonth, existing.Reason)
55		}
56	
57		// 起月须晚于该客户所有已封账月份：已封账账单不因暂停改变。
58		for _, b := range s.Bills {
59			if b.CustomerID == customerID && b.Month >= startMonth {
60				return fmt.Errorf("客户 %s 的 %s 已封账，暂停起月 %s 须晚于该客户所有已封账月份",
61					customerID, b.Month, startMonth)
62			}
63		}
64		// 同一客户的区间不得重叠（可以相接，相接视为连续暂停）；其他客户互不影响。
65		for _, su := range s.suspensionsFor(customerID) {
66			if startMonth < su.EndMonth && endMonth > su.StartMonth {
67				return fmt.Errorf("新区间 %s..%s（不含结束月）与客户 %s 已登记区间 %s..%s（不含结束月）重叠；区间可以相接但不得重叠",
68					startMonth, endMonth, customerID, su.StartMonth, su.EndMonth)
69			}
70		}
71		// 登记前检查区间内已导入的有效（未撤回）用量：存在任一条就拒绝并指出
72		// 冲突记录，不删除或改写任何用量；已撤回记录不参与冲突判断，可存在于
73		// 随后暂停的月份。
74		var conflicts []string
75		conflictMonths := make(map[string]bool)
76		for _, u := range s.Usage {
77			if s.isWithdrawn(u.ID) {
78				continue
79			}
80			if u.CustomerID != customerID {
81				continue
82			}
83			m := utcMonth(u.Time)
84			if monthInRange(m, startMonth, endMonth) {
85				conflicts = append(conflicts, fmt.Sprintf("用量 %s（%s，数量 %d）", u.ID, m, u.Quantity))
86				conflictMonths[m] = true
87			}
88		}
89		if len(conflicts) > 0 {
90			sort.Strings(conflicts)
91			months := make([]string, 0, len(conflictMonths))
92			for m := range conflictMonths {
93				months = append(months, m)
94			}
95			sort.Strings(months)
96			return fmt.Errorf("暂停区间 %s..%s（不含结束月）内已存在 %d 条用量（月份 %s），拒绝登记且不改写用量：%s",
97				startMonth, endMonth, len(conflicts), strings.Join(months, "、"), strings.Join(conflicts, "、"))
98		}
99	
100		su := &suspension{
101			CustomerID: customerID,
102			StartMonth: startMonth,
103			EndMonth:   endMonth,
104			Reason:     reason,
105			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
106		}
107		s.Suspensions[key] = su
108	
109		// 暂停记录整体原子落盘后才报告成功；保存失败则一切不生效，
110		// 该客户该起月不被占用，可原样重试。
111		if err := s.save(); err != nil {
112			delete(s.Suspensions, key)
113			return err
114		}
115		fmt.Fprintf(stdout, "已登记暂停区间：客户 %s 自 %s（UTC 自然月，含）至 %s（不含）暂停服务，期间不接收用量、不产生月费账单：\n\n",
116			customerID, startMonth, endMonth)
117		printSuspension(su)
118		return nil
119	}
120	
121	// printSuspension 输出一条暂停区间记录。
122	func printSuspension(su *suspension) {
123		fmt.Fprintf(stdout, "客户：%s\n", su.CustomerID)
124		fmt.Fprintf(stdout, "暂停区间：%s（含）至 %s（不含，UTC 自然月）\n", su.StartMonth, su.EndMonth)
125		fmt.Fprintf(stdout, "原因：%s\n", su.Reason)
126	}
127	
128	// describeSuspension 返回覆盖指定月份的暂停区间的简短描述，用于错误信息。
129	func describeSuspension(s *state, customerID, month string) string {
130		for _, su := range s.suspensionsFor(customerID) {
131			if monthInRange(month, su.StartMonth, su.EndMonth) {
132				return fmt.Sprintf("区间 %s（含）至 %s（不含），原因：%s", su.StartMonth, su.EndMonth, su.Reason)
133			}
134		}
135		return "暂停区间"
136	}
137	
138	func cmdCustomerSuspensions(dir, customerID, month string, hasMonth bool) error {
139		if hasMonth && !validMonth(month) {
140			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", month)
141		}
142	
143		s, err := loadStore(dir)
144		if err != nil {
145			return err
146		}
147		cust, ok := s.Customers[customerID]
148		if !ok {
149			return fmt.Errorf("客户标识 %q 不存在", customerID)
150		}
151	
152		// 只读查询：不改写存档、不占用序号、不新增记录；成功或失败均不落盘。
153		if cust.PlanID == "" {
154			fmt.Fprintf(stdout, "客户 %s（%s）是固定单价客户（单价 %d 分），不适用按月暂停，全部月份正常服务\n",
155				cust.ID, cust.Name, cust.Price)
156			if hasMonth {
157				fmt.Fprintf(stdout, "月份 %s：不适用暂停（固定单价客户正常服务）\n", month)
158			}
159			return nil
160		}
161	
162		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
163		list := s.suspensionsFor(customerID)
164		if len(list) == 0 {
165			fmt.Fprintln(stdout, "暂停区间：无（全部 UTC 自然月正常服务）")
166		} else {
167			fmt.Fprintln(stdout, "暂停区间（按起月升序；包含起月、不包含结束月）：")
168			for i, su := range list {
169				fmt.Fprintf(stdout, "  %d. %s（含）至 %s（不含），原因：%s\n",
170					i+1, su.StartMonth, su.EndMonth, su.Reason)
171			}
172		}
173		if hasMonth {
174			var hit *suspension
175			for _, su := range list {
176				if monthInRange(month, su.StartMonth, su.EndMonth) {
177					hit = su
178					break
179				}
180			}
181			if hit != nil {
182				fmt.Fprintf(stdout, "月份 %s：已暂停（处于区间 %s（含）至 %s（不含）），原因：%s\n",
183					month, hit.StartMonth, hit.EndMonth, hit.Reason)
184			} else {
185				fmt.Fprintf(stdout, "月份 %s：未暂停（不在任何暂停区间内，正常服务）\n", month)
186			}
187		}
188		return nil
189	}
