242		NewCustomerID string `json:"new_customer_id"`
243		NewTime       string `json:"new_time"` // RFC3339，保留首次更正的原始输入
244		NewQuantity   int64  `json:"new_quantity"`
245		Reason        string `json:"reason"` // 更正原因，同时是原记录的撤回原因，非空
246		CreatedAt     string `json:"created_at"`
247	}
