254		Bills       map[string]*bill        `json:"bills"`                 // 客户 + "|" + 月份 -> 账单
255		Adjustments map[string]*adjustment  `json:"adjustments"`           // 全局唯一调整标识 -> 记录
256		Payments    map[string]*payment     `json:"payments"`              // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
257		Corrections map[string]*correction  `json:"corrections"`           // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
