259		PlanChanges map[string]*planChange  `json:"plan_changes"`          // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
260		Suspensions map[string]*suspension  `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（不可改写）
261		Withdrawals map[string]*withdrawal  `json:"withdrawals,omitempty"` // 用量标识 -> 撤回标记（不可恢复，标识不可复用）
262		// UsageCorrections 以原用量标识为键保存用量更正关联；原记录同时在
263		// Withdrawals 中按更正原因标记撤回。旧存档缺少本字段视为无更正。
264		UsageCorrections map[string]*usageCorrection `json:"usage_corrections,omitempty"`
265		NextSeq          int64                       `json:"next_seq"` // 已分配的最大操作序号（调整/收款/更正/退款及其撤销共用；方案变更、暂停、用量撤回与用量更正不占用）
266		path             string                      `json:"-"`
267	}
