269	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
270	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
271	func loadStore(dir string) (*state, error) {
272		p := filepath.Join(dir, "state.json")
273		data, err := os.ReadFile(p)
274		if err != nil {
275			if errors.Is(err, os.ErrNotExist) {
276				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
277					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
278				}
279				return newState(p), nil
280			}
281			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
282		}
283	
284		var s state
285		dec := json.NewDecoder(bytes.NewReader(data))
286		if err := dec.Decode(&s); err != nil {
287			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
288		}
289		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
290		// 吞掉异常数据；合法尾随空白仍可读取。
291		if off := dec.InputOffset(); off < int64(len(data)) {
292			if strings.TrimSpace(string(data[off:])) != "" {
293				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
294			}
295		}
296		if err := s.validate(); err != nil {
297			return nil, fmt.Errorf("数据文件已损坏: %w", err)
298		}
299		// 旧版本数据文件没有 plans/adjustments/payments/corrections/refunds/
300		// plan_changes/suspensions/withdrawals/usage_corrections/next_seq 字段：
301		// 视为零方案、零调整、零实收、零更正、零退款、零方案变更、零暂停、
302		// 零撤回、零用量更正（全部用量有效）。
303		if s.Plans == nil {
304			s.Plans = map[string]*plan{}
305		}
306		if s.Adjustments == nil {
307			s.Adjustments = map[string]*adjustment{}
308		}
309		if s.Payments == nil {
310			s.Payments = map[string]*payment{}
311		}
312		if s.Corrections == nil {
313			s.Corrections = map[string]*correction{}
314		}
315		if s.Refunds == nil {
316			s.Refunds = map[string]*refund{}
317		}
318		if s.PlanChanges == nil {
319			s.PlanChanges = map[string]*planChange{}
320		}
321		if s.Suspensions == nil {
322			s.Suspensions = map[string]*suspension{}
323		}
324		if s.Withdrawals == nil {
325			s.Withdrawals = map[string]*withdrawal{}
326		}
327		if s.UsageCorrections == nil {
328			s.UsageCorrections = map[string]*usageCorrection{}
329		}
330		s.path = p
331		return &s, nil
332	}
333	
334	func newState(p string) *state {
335		return &state{
336			Version:          stateVersion,
337			Customers:        map[string]*customer{},
338			Plans:            map[string]*plan{},
339			Usage:            map[string]*usageRecord{},
340			Bills:            map[string]*bill{},
341			Adjustments:      map[string]*adjustment{},
342			Payments:         map[string]*payment{},
343			Corrections:      map[string]*correction{},
344			Refunds:          map[string]*refund{},
345			PlanChanges:      map[string]*planChange{},
346			Suspensions:      map[string]*suspension{},
347			Withdrawals:      map[string]*withdrawal{},
348			UsageCorrections: map[string]*usageCorrection{},
349			path:             p,
350		}
351	}
