353	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
354	func (s *state) validate() error {
355		if s.Version != stateVersion {
356			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
357		}
358		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
359			return errors.New("缺少必要的数据节")
360		}
361		for id, p := range s.Plans {
362			if p == nil {
363				return fmt.Errorf("方案 %q 的数据为空", id)
364			}
365			if p.ID != id {
366				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
367			}
368			if err := validatePlanRules(p); err != nil {
369				return err
370			}
371		}
372		for id, c := range s.Customers {
373			if c == nil {
374				return fmt.Errorf("客户 %q 的数据为空", id)
375			}
376			if c.ID != id {
377				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
378			}
379			if c.ID == "" || c.Name == "" {
380				return fmt.Errorf("客户 %q 的标识或名称为空", id)
381			}
382			if c.Price < 0 {
383				return fmt.Errorf("客户 %q 单价为负", id)
384			}
385			if c.PlanID != "" {
386				if _, ok := s.Plans[c.PlanID]; !ok {
387					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
388				}
389			}
390		}
391		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
392		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
393		for key, ch := range s.PlanChanges {
394			if ch == nil {
395				return fmt.Errorf("方案变更 %q 的数据为空", key)
396			}
397			if planChangeKey(ch.CustomerID, ch.Month) != key {
398				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
399			}
400			c, ok := s.Customers[ch.CustomerID]
401			if !ok {
402				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
403			}
404			if c.PlanID == "" {
405				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
406			}
407			if !validMonth(ch.Month) {
408				return fmt.Errorf("方案变更 %q 的生效月无效", key)
409			}
410			if _, ok := s.Plans[ch.PlanID]; !ok {
411				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
412			}
413			if strings.TrimSpace(ch.Reason) == "" {
414				return fmt.Errorf("方案变更 %q 的原因为空", key)
415			}
416		}
417		for id, u := range s.Usage {
418			if u == nil {
419				return fmt.Errorf("用量 %q 的数据为空", id)
420			}
421			if u.ID != id {
422				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
423			}
424			if u.ID == "" {
425				return errors.New("存在空的用量标识")
426			}
427			if _, ok := s.Customers[u.CustomerID]; !ok {
428				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
429			}
430			if u.Quantity <= 0 {
431				return fmt.Errorf("用量 %q 的数量非正", u.ID)
432			}
433			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
434				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
435			}
436		}
437		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
438		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
439		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
440		// 在载入时补为空表）。
441		for id, w := range s.Withdrawals {
442			if w == nil {
443				return fmt.Errorf("用量 %q 的撤回记录为空", id)
444			}
445			if w.UsageID != id {
446				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
447			}
448			if w.UsageID == "" {
449				return errors.New("存在空用量标识的撤回记录")
450			}
451			if _, ok := s.Usage[w.UsageID]; !ok {
452				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
453			}
454			if strings.TrimSpace(w.Reason) == "" {
455				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
456			}
457		}
458		// 用量更正关联：键与原标识一致；原记录与替代记录都必须存在于 Usage，
459		// 替代记录内容（客户、解析后的时间点、数量）须与更正保存的新内容一致；
460		// 原记录必须已按更正原因撤回（撤回标记的原因与更正原因不符即损坏）；
461		// 同一替代记录只能有一个来源；关联不得成环。替代记录后来被合法撤回或
462		// 继续更正（即它本身又作为某条更正的原记录）属正常状态，不判为损坏。
463		// 旧文件缺少更正记录视为无更正（UsageCorrections 已在载入时补为空表）。
464		replacementSources := make(map[string]string) // 替代用量标识 -> 原用量标识
465		for id, uc := range s.UsageCorrections {
466			if uc == nil {
467				return fmt.Errorf("用量更正 %q 的数据为空", id)
468			}
469			if uc.UsageID != id {
470				return fmt.Errorf("用量更正键不一致: 键 %q / 原用量标识 %q", id, uc.UsageID)
471			}
472			if uc.UsageID == "" {
473				return errors.New("存在空原用量标识的更正记录")
474			}
475			if strings.TrimSpace(uc.Reason) == "" {
476				return fmt.Errorf("用量更正 %q 的原因为空", id)
477			}
478			orig, ok := s.Usage[uc.UsageID]
479			if !ok {
480				return fmt.Errorf("用量更正 %q 引用了不存在的原用量 %q（更正来源失效）", id, uc.UsageID)
481			}
482			// 原记录内容不可改写：原用量记录仍须是正常的正数量有效格式（已在
483			// 上面的用量校验中核验），此处仅确认其存在。
484			if orig.ID != uc.UsageID {
485				return fmt.Errorf("用量更正 %q 的原记录标识不一致", id)
486			}
487			if uc.ReplacementID == "" {
488				return fmt.Errorf("用量更正 %q 缺少替代用量标识", id)
489			}
490			if uc.ReplacementID == uc.UsageID {
491				return fmt.Errorf("用量更正 %q 的替代标识与原标识相同", id)
492			}
493			repl, ok := s.Usage[uc.ReplacementID]
494			if !ok {
495				return fmt.Errorf("用量更正 %q 引用了不存在的替代用量 %q（更正目标失效）", id, uc.ReplacementID)
496			}
497			if src, dup := replacementSources[uc.ReplacementID]; dup {
498				return fmt.Errorf("替代用量 %q 同时是用量 %q 与 %q 的更正替代（同一替代记录不得有多个来源）",
499					uc.ReplacementID, src, uc.UsageID)
500			}
501			replacementSources[uc.ReplacementID] = uc.UsageID
502			if _, ok := s.Customers[uc.NewCustomerID]; !ok {
503				return fmt.Errorf("用量更正 %q 引用了不存在的新客户 %q", id, uc.NewCustomerID)
504			}
505			nt, err := time.Parse(time.RFC3339, uc.NewTime)
506			if err != nil {
507				return fmt.Errorf("用量更正 %q 的新时间不是 RFC3339: %w", id, err)
508			}
509			if uc.NewQuantity <= 0 {
510				return fmt.Errorf("用量更正 %q 的新数量非正", id)
511			}
512			rt, err := time.Parse(time.RFC3339, repl.Time)
513			if err != nil {
514				return fmt.Errorf("用量更正 %q 的替代记录 %q 时间不是 RFC3339: %w", id, uc.ReplacementID, err)
515			}
516			// 替代记录内容（客户、解析后的时间点、数量）必须与更正保存的新内容一致；
517			// 时间按瞬间比较，Z 与 +08:00 表示同一时刻视为一致。
518			if repl.CustomerID != uc.NewCustomerID || repl.Quantity != uc.NewQuantity || !rt.Equal(nt) {
519				return fmt.Errorf("用量更正 %q 的替代记录 %q 内容与保存的新内容不一致（更正关联损坏）",
520					id, uc.ReplacementID)
521			}
522			// 原记录必须已撤回，且撤回原因就是更正原因。
523			w, ok := s.Withdrawals[uc.UsageID]
524			if !ok {
525				return fmt.Errorf("用量更正 %q 的原用量 %q 未撤回（更正须把原记录按更正原因标记撤回）", id, uc.UsageID)
526			}
527			if w.Reason != uc.Reason {
528				return fmt.Errorf("用量更正 %q 的原用量 %q 撤回原因 %q 与更正原因 %q 不符",
529					id, uc.UsageID, w.Reason, uc.Reason)
530			}
531		}
532		// 关联成环检测：沿“原记录 -> 替代记录”的更正链前进，重复访问即成环。
533		// 合法链必然终止于一条未再被更正的记录。
534		for id := range s.UsageCorrections {
535			seen := map[string]bool{id: true}
536			cur := id
537			for {
538				uc, ok := s.UsageCorrections[cur]
539				if !ok {
540					break // 链终止于未再被更正的记录
541				}
542				if seen[uc.ReplacementID] {
543					return fmt.Errorf("用量更正关联在 %q 处成环（更正链不得成环）", uc.ReplacementID)
544				}
545				seen[uc.ReplacementID] = true
546				cur = uc.ReplacementID
547			}
548		}
549		for key, b := range s.Bills {
550			if b == nil {
551				return fmt.Errorf("账单 %q 的数据为空", key)
552			}
553			if billKey(b.CustomerID, b.Month) != key {
554				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
555			}
556			if _, ok := s.Customers[b.CustomerID]; !ok {
557				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
558			}
559			if !validMonth(b.Month) {
560				return fmt.Errorf("账单 %q 的月份无效", key)
561			}
562			if b.MonthlyFee < 0 {
563				return fmt.Errorf("账单 %q 的月费为负", key)
564			}
565			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
566			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
567				return fmt.Errorf("账单 %q 没有明细", key)
568			}
569			var qty, fee int64
570			for _, ln := range b.Lines {
571				u, ok := s.Usage[ln.UsageID]
572				if !ok {
573					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
574				}
575				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
576				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
577					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
578				}
579				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
580					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
581				}
582				if !inMonth(u.Time, b.Month) {
583					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
584				}
585				var err error
586				qty, err = add64(qty, ln.Quantity)
587				if err != nil {
588					return fmt.Errorf("账单 %q 汇总数量溢出", key)
589				}
590				fee, err = add64(fee, ln.LineFee)
591				if err != nil {
592					return fmt.Errorf("账单 %q 汇总金额溢出", key)
593				}
594			}
595			if qty != b.TotalQty {
596				return fmt.Errorf("账单 %q 总数量与明细不符", key)
597			}
598			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
599			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
600			// 不会溢出；总金额为负或小于月费时此处必然不符。
601			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
602				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
603					key, fee, b.MonthlyFee, b.TotalFee)
604			}
605			c := s.Customers[b.CustomerID]
606			switch b.Pricing {
607			case "", "fixed":
608				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
609				// 携带阶梯方案信息、分段或月费。
610				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
611					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
612				}
613				if b.MonthlyFee != 0 {
614					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
615				}
616				for _, ln := range b.Lines {
617					if len(ln.Segments) > 0 {
618						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
619					}
620					lf, err := mul64(ln.Quantity, c.Price)
621					if err != nil {
622						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
623					}
624					if lf != ln.LineFee {
625						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
626					}
627				}
628				if b.UnitPrice != c.Price {
629					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
630				}
631			case "tiered":
632				if err := s.validateTieredBill(key, b, c); err != nil {
633					return err
634				}
635			default:
636				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
637			}
638			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
639			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
640			// 于已封账月份而不进入账单。
641			for _, u := range s.Usage {
642				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
643					continue
644				}
645				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
646					found := false
647					for _, ln := range b.Lines {
648						if ln.UsageID == u.ID {
649							found = true
650							break
651						}
652					}
653					if !found {
654						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
655					}
656				}
657			}
658		}
659	
660		// 暂停区间：键、客户（须为绑定阶梯方案的客户）、区间与原因都必须自洽；
661		// 同一客户的区间不得重叠（可以相接）；暂停月内不得存在有效（未撤回）
662		// 用量或账单。
663		// 旧文件缺少暂停记录视为正常服务（Suspensions 已在载入时补为空表）。
664		for key, su := range s.Suspensions {
665			if su == nil {
666				return fmt.Errorf("暂停区间 %q 的数据为空", key)
667			}
668			if suspensionKey(su.CustomerID, su.StartMonth) != key {
669				return fmt.Errorf("暂停区间键不一致: 键 %q / 客户起月 %s|%s", key, su.CustomerID, su.StartMonth)
670			}
671			c, ok := s.Customers[su.CustomerID]
672			if !ok {
673				return fmt.Errorf("暂停区间 %q 引用了不存在的客户 %q", key, su.CustomerID)
674			}
675			if c.PlanID == "" {
676				return fmt.Errorf("暂停区间 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用暂停）", key, su.CustomerID)
677			}
678			if !validMonth(su.StartMonth) {
679				return fmt.Errorf("暂停区间 %q 的起月无效", key)
680			}
681			if !validMonth(su.EndMonth) || su.EndMonth <= su.StartMonth {
682				return fmt.Errorf("暂停区间 %q 的结束月无效（结束月必须是晚于起月 %s 的 YYYY-MM）", key, su.StartMonth)
683			}
684			if strings.TrimSpace(su.Reason) == "" {
685				return fmt.Errorf("暂停区间 %q 的原因为空", key)
686			}
687		}
688		for customerID := range s.Customers {
689			list := s.suspensionsFor(customerID)
690			for i := 1; i < len(list); i++ {
691				if list[i].StartMonth < list[i-1].EndMonth {
692					return fmt.Errorf("客户 %s 的暂停区间 %s..%s 与 %s..%s 重叠（区间可以相接但不得重叠）",
693						customerID, list[i-1].StartMonth, list[i-1].EndMonth, list[i].StartMonth, list[i].EndMonth)
694				}
695			}
696			for _, su := range list {
697				for _, u := range s.Usage {
698					// 已撤回用量不参与用量冲突判断，可存在于随后暂停的月份。
699					if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
700						continue
701					}
702					if u.CustomerID == customerID && monthInRange(utcMonth(u.Time), su.StartMonth, su.EndMonth) {
703						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在用量 %q（%s）",
704							customerID, su.StartMonth, su.EndMonth, u.ID, utcMonth(u.Time))
705					}
706				}
707				for _, b := range s.Bills {
708					if b.CustomerID == customerID && monthInRange(b.Month, su.StartMonth, su.EndMonth) {
709						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在账单（月份 %s），暂停月不得封账",
710							customerID, su.StartMonth, su.EndMonth, b.Month)
711					}
712				}
713			}
714		}
715	
716		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
717		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
718		// 允许同名，各自判重与撤销。
719		if s.NextSeq < 0 {
720			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
721		}
722		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
723		for id, a := range s.Adjustments {
724			if a == nil {
725				return fmt.Errorf("调整 %q 的数据为空", id)
726			}
727			if a.ID != id {
728				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
729			}
730			if a.ID == "" {
731				return errors.New("存在空的调整标识")
732			}
733			if a.Amount == 0 {
734				return fmt.Errorf("调整 %q 的金额为零", id)
735			}
736			if strings.TrimSpace(a.Reason) == "" {
737				return fmt.Errorf("调整 %q 的原因为空", id)
738			}
739			if !validMonth(a.Month) {
740				return fmt.Errorf("调整 %q 的月份无效", id)
741			}
742			if _, ok := s.Customers[a.CustomerID]; !ok {
743				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
744			}
745			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
746				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
747			}
748			if a.Seq < 1 || a.Seq > s.NextSeq {
749				return fmt.Errorf("调整 %q 的操作序号越界", id)
750			}
751			if prev, dup := seenSeq[a.Seq]; dup {
752				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
753			}
754			seenSeq[a.Seq] = "调整 " + id
755			if a.Revoked {
756				if strings.TrimSpace(a.RevokeReason) == "" {
757					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
758				}
759				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
760					return fmt.Errorf("调整 %q 的撤销序号越界", id)
761				}
762				if prev, dup := seenSeq[a.RevokeSeq]; dup {
763					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
764				}
765				seenSeq[a.RevokeSeq] = "撤销调整 " + id
766			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
767				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
768			}
769		}
770		for id, p := range s.Payments {
771			if p == nil {
772				return fmt.Errorf("收款 %q 的数据为空", id)
773			}
774			if p.ID != id {
775				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
776			}
777			if p.ID == "" {
778				return errors.New("存在空的收款标识")
779			}
780			if p.Total <= 0 {
781				return fmt.Errorf("收款 %q 的总额不是正整数", id)
782			}
783			if strings.TrimSpace(p.Note) == "" {
784				return fmt.Errorf("收款 %q 的备注为空", id)
785			}
786			if _, ok := s.Customers[p.CustomerID]; !ok {
787				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
788			}
789			if len(p.Allocations) == 0 {
790				return fmt.Errorf("收款 %q 没有分配", id)
791			}
792			seenMonths := make(map[string]bool)
793			var sum int64
794			for _, al := range p.Allocations {
795				if !validMonth(al.Month) {
796					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
797				}
798				if seenMonths[al.Month] {
799					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
800				}
801				seenMonths[al.Month] = true
802				if al.Amount <= 0 {
803					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
804				}
805				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
806					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
807				}
808				var err error
809				sum, err = add64(sum, al.Amount)
810				if err != nil {
811					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
812				}
813			}
814			if sum != p.Total {
815				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
816			}
817			if p.Seq < 1 || p.Seq > s.NextSeq {
818				return fmt.Errorf("收款 %q 的操作序号越界", id)
819			}
820			if prev, dup := seenSeq[p.Seq]; dup {
821				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
822			}
823			seenSeq[p.Seq] = "收款 " + id
824			if p.Revoked {
825				if strings.TrimSpace(p.RevokeReason) == "" {
826					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
827				}
828				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
829					return fmt.Errorf("收款 %q 的撤销序号越界", id)
830				}
831				if prev, dup := seenSeq[p.RevokeSeq]; dup {
832					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
833				}
834				seenSeq[p.RevokeSeq] = "撤销收款 " + id
835			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
836				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
837			}
838		}
839		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
840		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
841		for id, c := range s.Corrections {
842			if c == nil {
843				return fmt.Errorf("更正 %q 的数据为空", id)
844			}
845			if c.ID != id {
846				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
847			}
848			if c.ID == "" {
849				return errors.New("存在空的更正标识")
850			}
851			p, ok := s.Payments[c.PaymentID]
852			if !ok {
853				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
854			}
855			if strings.TrimSpace(c.Reason) == "" {
856				return fmt.Errorf("更正 %q 的原因为空", id)
857			}
858			if len(c.Allocations) == 0 {
859				return fmt.Errorf("更正 %q 没有新分配", id)
860			}
861			seenMonths := make(map[string]bool)
862			var sum int64
863			for _, al := range c.Allocations {
864				if !validMonth(al.Month) {
865					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
866				}
867				if seenMonths[al.Month] {
868					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
869				}
870				seenMonths[al.Month] = true
871				if al.Amount <= 0 {
872					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
873				}
874				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
875					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
876				}
877				var err error
878				sum, err = add64(sum, al.Amount)
879				if err != nil {
880					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
881				}
882			}
883			if sum != p.Total {
884				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
885			}
886			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
887				return fmt.Errorf("更正 %q 的操作序号越界", id)
888			}
889			if p.Revoked && c.Seq > p.RevokeSeq {
890				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
891			}
892			if prev, dup := seenSeq[c.Seq]; dup {
893				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
894			}
895			seenSeq[c.Seq] = "更正 " + id
896		}
897		// 退款记录：标识、目标收款、原因、各月退款与序号都必须自洽。退款标识与
898		// 收款、调整、更正标识命名空间相互独立，允许同名。退款只作用于未撤销
899		// 收款的最新分配涉及的月份；首次退款后该收款不得再更正或整笔撤销，
900		// 因此全部退款都以当前最新分配为准核验，累计不得超退。旧文件缺少退款
901		// 记录视为无退款（Refunds 已在载入时补为空表）。
902		for id, r := range s.Refunds {
903			if r == nil {
904				return fmt.Errorf("退款 %q 的数据为空", id)
905			}
906			if r.ID != id {
907				return fmt.Errorf("退款标识不一致: 键 %q / 记录 %q", id, r.ID)
908			}
909			if r.ID == "" {
910				return errors.New("存在空的退款标识")
911			}
912			p, ok := s.Payments[r.PaymentID]
913			if !ok {
914				return fmt.Errorf("退款 %q 引用了不存在的收款 %q（退款目标失效）", id, r.PaymentID)
915			}
916			if strings.TrimSpace(r.Reason) == "" {
917				return fmt.Errorf("退款 %q 的原因为空", id)
918			}
919			if len(r.Allocations) == 0 {
920				return fmt.Errorf("退款 %q 没有月份金额清单", id)
921			}
922			current := currentAllocations(s, p)
923			seenMonths := make(map[string]bool)
924			for _, al := range r.Allocations {
925				if !validMonth(al.Month) {
926					return fmt.Errorf("退款 %q 的月份 %q 无效", id, al.Month)
927				}
928				if seenMonths[al.Month] {
929					return fmt.Errorf("退款 %q 的月份 %s 重复", id, al.Month)
930				}
931				seenMonths[al.Month] = true
932				if al.Amount <= 0 {
933					return fmt.Errorf("退款 %q 在 %s 的金额不是正整数", id, al.Month)
934				}
935				if allocAmountFor(current, al.Month) <= 0 {
936					return fmt.Errorf("退款 %q 的月份 %s 不在收款 %q 的最新分配中（仅允许退最新分配涉及的月份）", id, al.Month, r.PaymentID)
937				}
938			}
939			if r.Seq <= p.Seq || r.Seq > s.NextSeq {
940				return fmt.Errorf("退款 %q 的操作序号越界", id)
941			}
942			if prev, dup := seenSeq[r.Seq]; dup {
943				return fmt.Errorf("退款 %q 与 %q 的操作序号重复", id, prev)
944			}
945			seenSeq[r.Seq] = "退款 " + id
946		}
947		// 逐收款核验退款相关约束：已退款的收款不得被整笔撤销；首次退款后不得
948		// 再出现更正（最新分配已固定）；各月累计退款不得超过该笔在该月的最新
949		// 分配（累计超退即余额异常）。
950		for pid, p := range s.Payments {
951			refs := refundsFor(s, pid)
952			if len(refs) == 0 {
953				continue
954			}
955			firstRefundSeq := refs[0].Seq // refundsFor 按序号升序
956			if p.Revoked {
957				return fmt.Errorf("收款 %q 已发生退款（首次退款序号 %d）却又被整笔撤销（序号 %d），操作先后非法", pid, firstRefundSeq, p.RevokeSeq)
958			}
959			for _, c := range s.Corrections {
960				if c.PaymentID == pid && c.Seq > firstRefundSeq {
961					return fmt.Errorf("更正 %q 的序号 %d 晚于收款 %q 的首次退款序号 %d（首次退款后最新分配已固定），操作先后非法", c.ID, c.Seq, pid, firstRefundSeq)
962				}
963			}
964			current := currentAllocations(s, p)
965			totals := make(map[string]int64)
966			for _, r := range refs {
967				for _, al := range r.Allocations {
968					sum, err := add64(totals[al.Month], al.Amount)
969					if err != nil {
970						return fmt.Errorf("收款 %q 在 %s 的累计退款溢出有符号 64 位整数范围，余额异常", pid, al.Month)
971					}
972					totals[al.Month] = sum
973				}
974			}
975			for month, refunded := range totals {
976				if alloc := allocAmountFor(current, month); refunded > alloc {
977					return fmt.Errorf("收款 %q 在 %s 的累计退款 %d 分超过该月分配 %d 分（累计超退），余额异常", pid, month, refunded, alloc)
978				}
979			}
980		}
981		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
982		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
983		// 计入并扣除退款后的合计）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明
984		// 金额与记录不一致。
985		for key, b := range s.Bills {
986			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
987			if err != nil {
988				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
989			}
990			received, err := paymentReceived(s, b.CustomerID, b.Month)
991			if err != nil {
992				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
993			}
994			if received > payable {
995				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
996			}
997		}
998		return nil
999	}
