1001	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
1002	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
1003	// 上限，单价非负。
1004	func validatePlanRules(p *plan) error {
1005		if p.ID == "" || p.Name == "" {
1006			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
1007		}
1008		if p.MonthlyFee < 0 {
1009			return fmt.Errorf("方案 %q 的月费为负", p.ID)
1010		}
1011		if len(p.Tiers) == 0 {
1012			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
1013		}
1014		prev := int64(0)
1015		for i, t := range p.Tiers {
1016			if t.Price < 0 {
1017				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
1018			}
1019			if i == len(p.Tiers)-1 {
1020				if t.Limit != 0 {
1021					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
1022				}
1023			} else {
1024				if t.Limit <= 0 {
1025					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
1026				}
1027				if t.Limit <= prev {
1028					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
1029				}
1030				prev = t.Limit
1031			}
1032		}
1033		return nil
1034	}
