1062	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
1063	// 标识字典序）排列，即阶梯计价的计价顺序。
1064	func sortedByInstant(recs []*usageRecord) bool {
1065		for i := 1; i < len(recs); i++ {
1066			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
1067			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
1068			ui, uj := ti.UTC(), tj.UTC()
1069			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
1070				return false
1071			}
1072		}
1073		return true
1074	}
