1076	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
1077	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
1078	// 小计、各档合计与总金额；任何不符都视为数据损坏。
1079	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
1080		if b.PlanID == "" {
1081			return fmt.Errorf("账单 %q 缺少方案标识", key)
1082		}
1083		p, ok := s.Plans[b.PlanID]
1084		if !ok {
1085			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
1086		}
1087		if b.PlanName != p.Name {
1088			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
1089		}
1090		if !tiersEqual(b.PlanTiers, p.Tiers) {
1091			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
1092		}
1093		if b.MonthlyFee != p.MonthlyFee {
1094			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
1095		}
1096		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
1097		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
1098		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
1099			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
1100		}
1101		if b.UnitPrice != 0 {
1102			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
1103		}
1104		if len(b.TierTotals) != len(p.Tiers) {
1105			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
1106		}
1107		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
1108		recs := make([]*usageRecord, len(b.Lines))
1109		for i, ln := range b.Lines {
1110			recs[i] = s.Usage[ln.UsageID]
1111		}
1112		if !sortedByInstant(recs) {
1113			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
1114		}
1115		priced, err := tieredPrice(p.Tiers, recs)
1116		if err != nil {
1117			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
1118		}
1119		for i, ln := range b.Lines {
1120			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1121				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1122			}
1123			if ln.LineFee != priced.lines[i].fee {
1124				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1125			}
1126		}
1127		for i, tt := range b.TierTotals {
1128			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1129				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1130			}
1131		}
1132		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1133		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1134		if err != nil || wantTotal != b.TotalFee {
1135			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1136		}
1137		return nil
1138	}
