1140	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1141	// 只有完整保存成功后调用方才会向用户报告成功。
1142	func (s *state) save() error {
1143		if err := s.validate(); err != nil {
1144			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1145		}
1146		data, err := json.MarshalIndent(s, "", "  ")
1147		if err != nil {
1148			return fmt.Errorf("序列化数据失败: %w", err)
1149		}
1150		data = append(data, '\n')
1151	
1152		tmp := s.path + ".tmp"
1153		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1154		if err != nil {
1155			return fmt.Errorf("写入临时数据文件失败: %w", err)
1156		}
1157		if _, err := f.Write(data); err != nil {
1158			f.Close()
1159			os.Remove(tmp)
1160			return fmt.Errorf("写入临时数据文件失败: %w", err)
1161		}
1162		if err := f.Sync(); err != nil {
1163			f.Close()
1164			os.Remove(tmp)
1165			return fmt.Errorf("同步数据文件失败: %w", err)
1166		}
1167		if err := f.Close(); err != nil {
1168			os.Remove(tmp)
1169			return fmt.Errorf("关闭数据文件失败: %w", err)
1170		}
1171		if err := os.Rename(tmp, s.path); err != nil {
1172			os.Remove(tmp)
1173			return fmt.Errorf("替换数据文件失败: %w", err)
1174		}
1175		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1176			dir.Sync()
1177			dir.Close()
1178		}
1179		return nil
1180	}
