1212	// isSuspendedMonth 报告某客户的指定 UTC 自然月是否处于任一暂停区间内
1213	// （区间包含起月、不包含结束月；相接区间视为连续暂停）。
1214	func (s *state) isSuspendedMonth(customerID, month string) bool {
1215		for _, su := range s.Suspensions {
1216			if su.CustomerID == customerID && monthInRange(month, su.StartMonth, su.EndMonth) {
1217				return true
1218			}
1219		}
1220		return false
1221	}
1222	
1223	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
1224	func (s *state) planChangesFor(customerID string) []*planChange {
1225		var list []*planChange
1226		for _, ch := range s.PlanChanges {
1227			if ch.CustomerID == customerID {
1228				list = append(list, ch)
1229			}
1230		}
1231		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
1232		return list
1233	}
1234	
1235	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
1236	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
1237	func (s *state) effectivePlanID(cust *customer, month string) string {
1238		planID := cust.PlanID
1239		latest := ""
1240		for _, ch := range s.PlanChanges {
1241			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
1242				latest = ch.Month
1243				planID = ch.PlanID
1244			}
1245		}
1246		return planID
1247	}
1248	
1249	// sealed 报告某客户的指定月份是否已封账。
1250	func (s *state) sealed(customerID, month string) bool {
1251		_, ok := s.Bills[billKey(customerID, month)]
1252		return ok
1253	}
1254	
1255	// isWithdrawn 报告指定用量标识是否已撤回。已撤回用量不参与结算、方案变更
1256	// 预检与暂停区间冲突检查，但原记录永久保留并继续参与导入判重。
1257	func (s *state) isWithdrawn(usageID string) bool {
1258		_, ok := s.Withdrawals[usageID]
1259		return ok
1260	}
1261	
1262	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
1263	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
1264		var list []*adjustment
1265		for _, a := range s.Adjustments {
1266			if a.CustomerID == customerID && a.Month == month {
1267				list = append(list, a)
1268			}
1269		}
1270		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1271		return list
1272	}
1273	
1274	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
1275	func correctionsFor(s *state, paymentID string) []*correction {
1276		var list []*correction
1277		for _, c := range s.Corrections {
1278			if c.PaymentID == paymentID {
1279				list = append(list, c)
1280			}
1281		}
1282		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1283		return list
1284	}
1285	
1286	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
1287	// 原始分配，否则为序号最大（最新）的更正的分配。
1288	func currentAllocations(s *state, p *payment) []paymentAllocation {
1289		var latest *correction
1290		for _, c := range s.Corrections {
1291			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
1292				latest = c
1293			}
1294		}
1295		if latest != nil {
1296			return latest.Allocations
1297		}
1298		return p.Allocations
1299	}
1300	
1301	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
1302	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
1303		for _, al := range allocs {
1304			if al.Month == month {
1305				return al.Amount
1306			}
1307		}
1308		return 0
1309	}
1310	
1311	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
1312	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
1313	func paymentsEverFor(s *state, customerID, month string) []*payment {
1314		var list []*payment
1315		for _, p := range s.Payments {
1316			if p.CustomerID != customerID {
1317				continue
1318			}
1319			involved := p.amountFor(month) > 0
1320			if !involved {
1321				for _, c := range s.Corrections {
1322					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1323						involved = true
1324						break
1325					}
1326				}
1327			}
1328			if involved {
1329				list = append(list, p)
1330			}
1331		}
1332		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1333		return list
1334	}
1335	
1336	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入并扣除退款后
1337	// 的实收之和。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1338	// 累加，溢出时返回错误。
1339	func paymentReceived(s *state, customerID, month string) (int64, error) {
1340		var received int64
1341		for _, p := range s.Payments {
1342			if p.CustomerID != customerID || p.Revoked {
1343				continue
1344			}
1345			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1346			if amt <= 0 {
1347				continue
1348			}
1349			var err error
1350			received, err = add64(received, amt)
1351			if err != nil {
1352				return 0, err
1353			}
1354		}
1355		return received, nil
1356	}
1357	
1358	// refundsFor 返回某收款的全部退款，按操作序号升序。
1359	func refundsFor(s *state, paymentID string) []*refund {
1360		var list []*refund
1361		for _, r := range s.Refunds {
1362			if r.PaymentID == paymentID {
1363				list = append(list, r)
1364			}
1365		}
1366		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1367		return list
1368	}
1369	
1370	// refundedForMonth 返回某收款在指定月份的累计退款金额（分）；无退款时为 0。
1371	// 数据在载入时已校验累计不超退，合计不超过该月分配，不会溢出。
1372	func refundedForMonth(s *state, paymentID, month string) int64 {
1373		var total int64
1374		for _, r := range s.Refunds {
1375			if r.PaymentID == paymentID {
1376				total += allocAmountFor(r.Allocations, month)
1377			}
1378		}
1379		return total
1380	}
1381	
1382	// paymentHasRefunds 报告某收款是否已发生退款。首次退款后该收款的最新分配
1383	// 固定，不得再新增分配更正或整笔撤销。
1384	func paymentHasRefunds(s *state, paymentID string) bool {
1385		for _, r := range s.Refunds {
1386			if r.PaymentID == paymentID {
1387				return true
1388			}
1389		}
1390		return false
1391	}
1392	
1393	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1394	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1395	
1396	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1397	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1398	// [0, 有符号 64 位最大值] 内，全程整数运算。
1399	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1400		var amounts []int64
1401		for _, a := range adjs {
1402			if !a.Revoked {
1403				amounts = append(amounts, a.Amount)
1404			}
1405		}
1406		net, err = sumSigned64(amounts...)
1407		if err != nil {
1408			return 0, 0, err
1409		}
1410		payable, err = addSigned64(b.TotalFee, net)
1411		if err != nil {
1412			return 0, 0, err
1413		}
1414		if payable < 0 {
1415			return 0, 0, errPayableOutOfRange
1416		}
1417		return net, payable, nil
1418	}
1419

