192				return cmdBillRefund(dataDir, args[2], args[3], args[4], args[5:])
193			case "ledger":
194				if len(args) != 4 && len(args) != 5 {
195					return usageError("用法：bill ledger <客户标识> <YYYY-MM> [截止操作序号]")
196				}
197				cutoff, hasCutoff := "", false
198				if len(args) == 5 {
199					cutoff, hasCutoff = args[4], true
200				}
201				return cmdBillLedger(dataDir, args[2], args[3], cutoff, hasCutoff)
202			case "reconcile":
203				if len(args) != 5 && len(args) != 7 {
204					return usageError("用法：bill reconcile <客户标识> <起月 YYYY-MM> <止月 YYYY-MM> [起始操作序号 截止操作序号]")
205				}
206				return cmdBillReconcile(dataDir, args[2], args[3], args[4], args[5:])
207			default:
208				return usageError("未知 bill 子命令 %q；可用：settle、settle-batch、show、adjust、revoke、pay、remit、remit-auto、correct、unpay、refund、ledger、reconcile", args[1])
209			}
210	
211		default:
212			return usageError("未知命令 %q；可用：customer、plan、usage、bill", args[0])
213		}
214	}
