269	
270	func cmdUsageImport(dir, file string) error {
271		var reader io.ReadCloser
272		var source string
273		if file == "-" {
274			reader = io.NopCloser(os.Stdin)
275			source = "标准输入"
276		} else {
277			f, err := os.Open(file)
278			if err != nil {
279				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
280			}
281			reader = f
282			source = file
283		}
284		defer reader.Close()
285	
286		rows, parseErrs := parseUsageFile(reader)
287	
288		s, err := loadStore(dir)
289		if err != nil {
290			return err
291		}
292	
293		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
294		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
295		var problems []string
296		problems = append(problems, parseErrs...)
297	
298		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
299		var ordered []*parsedRow
300		newCount, dupCount := 0, 0
301	
302		for _, r := range rows {
303			cust, ok := s.Customers[r.rec.CustomerID]
304			if !ok {
305				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
306				continue
307			}
308	
309			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
310			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
311			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
312			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
313			var existing *usageRecord
314			if inStore, ok := s.Usage[r.rec.ID]; ok {
315				existing = inStore
316			} else if inBatch, ok := accepted[r.rec.ID]; ok {
317				existing = &inBatch.rec
318			}
319			if existing != nil {
320				if !sameUsage(existing, &r.rec, r.t) {
321					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
322						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
323					continue
324				}
325				dupCount++
326				continue
327			}
328	
329			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
330			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
331			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
332			rowMonth := r.t.UTC().Format("2006-01")
333			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
334				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
335					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
336				continue
337			}
338			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
339			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
340			// 溢出（金额单位：分）。
341			if cust.PlanID == "" {
342				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
343					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
344					continue
345				}
346			} else {
347				rec := r.rec
348				planID := s.effectivePlanID(cust, rowMonth)
349				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
350					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
351					continue
352				}
353			}
354	
355			// 全新标识：不得进入该客户已封账的 UTC 自然月。
356			if s.sealed(r.rec.CustomerID, rowMonth) {
357				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
358					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
359				continue
360			}
361	
362			rr := r
363			accepted[r.rec.ID] = rr
364			ordered = append(ordered, rr)
365			newCount++
366		}
367	
368		if len(problems) > 0 {
369			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
370		}
371	
372		for _, r := range ordered {
373			rec := r.rec
374			s.Usage[rec.ID] = &rec
375		}
376		if err := s.save(); err != nil {
377			return err
378		}
379		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
380		return nil
381	}
