383	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
384	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
385		cr := csv.NewReader(r)
386		cr.FieldsPerRecord = 4
387		cr.TrimLeadingSpace = true
388	
389		header, err := cr.Read()
390		if err == io.EOF {
391			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
392		}
393		if err != nil {
394			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
395		}
396		for i := range header {
397			header[i] = strings.TrimSpace(header[i])
398		}
399		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
400			header[2] != "time" || header[3] != "quantity" {
401			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
402		}
403	
404		var rows []*parsedRow
405		var problems []string
406		line := 1
407		for {
408			rec, err := cr.Read()
409			if err == io.EOF {
410				break
411			}
412			line++
413			if err != nil {
414				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
415				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
416					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
417					break
418				}
419				continue
420			}
421			for i := range rec {
422				rec[i] = strings.TrimSpace(rec[i])
423			}
424	
425			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
426			if id == "" {
427				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
428				continue
429			}
430			if custID == "" {
431				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
432				continue
433			}
434			t, err := time.Parse(time.RFC3339, ts)
435			if err != nil {
436				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
437				continue
438			}
439			qty, err := strconv.ParseInt(qtyText, 10, 64)
440			if err != nil {
441				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
442				continue
443			}
444			if qty <= 0 {
445				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
446				continue
447			}
448	
449			rows = append(rows, &parsedRow{
450				line: line,
451				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
452				t:    t,
453			})
454		}
455		return rows, problems
456	}
457	
458	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
459	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
460	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
461		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
462			return false
463		}
464		et, err := time.Parse(time.RFC3339, existing.Time)
465		if err != nil {
466			return existing.Time == candidate.Time
467		}
468		return et.Equal(candidateT)
469	}
470	
471	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
472	func validMonth(m string) bool {
473		t, err := time.Parse("2006-01", m)
474		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
475			return false
476		}
477		return true
478	}
479	
480	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
481	func inMonth(rfc3339, month string) bool {
482		t, err := time.Parse(time.RFC3339, rfc3339)
483		if err != nil {
484			return false
485		}
486		return t.UTC().Format("2006-01") == month
487	}
488	
489	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
490	// 入参时间均已在载入/导入时校验为 RFC3339。
491	func utcMonth(rfc3339 string) string {
492		t, _ := time.Parse(time.RFC3339, rfc3339)
493		return t.UTC().Format("2006-01")
494	}
