496	func cmdBillSettle(dir, customerID, month string) error {
497		if !validMonth(month) {
498			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
499		}
500		s, err := loadStore(dir)
501		if err != nil {
502			return err
503		}
504		cust, ok := s.Customers[customerID]
505		if !ok {
506			return fmt.Errorf("客户标识 %q 不存在", customerID)
507		}
508	
509		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
510		if s.isSuspendedMonth(customerID, month) {
511			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
512		}
513	
514		key := billKey(customerID, month)
515		if existing, ok := s.Bills[key]; ok {
516			// 幂等：同一客户同一月份重复结算，直接返回原账单，
517			// 不重新计费、不产生新账单或调整、不落盘。
518			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
519			printBill(existing, cust, s)
520			return nil
521		}
522	
523		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
524		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
525		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
526		// 结算且不封账。
527		inMonthRecs := monthUsage(s, customerID, month)
528		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
529			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
530		}
531	
532		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
533		if cust.PlanID != "" {
534			return settleTiered(s, cust, month, inMonthRecs)
535		}
536	
537		b, err := buildFixedBill(cust, month, inMonthRecs)
538		if err != nil {
539			return fmt.Errorf("%v，拒绝结算且不封账", err)
540		}
541		s.Bills[key] = b
542	
543		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
544		if err := s.save(); err != nil {
545			delete(s.Bills, key)
546			return err
547		}
548		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
549		printBill(b, cust, s)
550		return nil
551	}
