573	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
574	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
575	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
576	// 记录按原有时间点及标识顺序从零累计重新分档。
577	func monthUsage(s *state, customerID, month string) []*usageRecord {
578		var recs []*usageRecord
579		for _, u := range s.Usage {
580			if s.isWithdrawn(u.ID) {
581				continue
582			}
583			if u.CustomerID == customerID && inMonth(u.Time, month) {
584				recs = append(recs, u)
585			}
586		}
587		sortByInstant(recs)
588		return recs
589	}
590	
591	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
592	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
593	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
594		lines := make([]billLine, 0, len(recs))
595		var totalQty, totalFee int64
596		for _, u := range recs {
597			lineFee, err := mul64(u.Quantity, cust.Price)
598			if err != nil {
599				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
600			}
601			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
602				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
603			}
604			if totalFee, err = add64(totalFee, lineFee); err != nil {
605				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
606			}
607			lines = append(lines, billLine{
608				UsageID:  u.ID,
609				Time:     u.Time,
610				Quantity: u.Quantity,
611				LineFee:  lineFee,
612			})
613		}
614		return &bill{
615			ID:         stableBillID(cust.ID, month),
616			CustomerID: cust.ID,
617			Month:      month,
618			TotalQty:   totalQty,
619			UnitPrice:  cust.Price,
620			TotalFee:   totalFee,
621			Lines:      lines,
622			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
623		}, nil
624	}
625	
626	func sortByInstant(us []*usageRecord) {
627		// 入参时间均已在载入/导入时校验为 RFC3339。
628		sort.Slice(us, func(i, j int) bool {
629			ti, _ := time.Parse(time.RFC3339, us[i].Time)
630			tj, _ := time.Parse(time.RFC3339, us[j].Time)
631			ui, uj := ti.UTC(), tj.UTC()
632			if !ui.Equal(uj) {
633				return ui.Before(uj)
634			}
635			return us[i].ID < us[j].ID
636		})
637	}
638	
639	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
640	func stableBillID(customerID, month string) string {
641		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
642		return "BILL-" + hex.EncodeToString(sum[:])[:16]
643	}
644	
645	func printBill(b *bill, cust *customer, s *state) {
646		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
647		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
648		// 涉及该月即纳入，即使后来被更正移出。
649		pays := paymentsEverFor(s, b.CustomerID, b.Month)
650		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
651		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
652		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
653		tiered := b.Pricing == "tiered"
654		if tiered {
