664				}
665			}
666		} else {
667			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
668		}
669		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
670		if tiered {
671			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
672			// 月费不计入总数量、各档金额或逐条小计。
673			usageFee := b.TotalFee - b.MonthlyFee
674			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
