688		net, payable, _ := billTotals(b, adjs)
689		received, _ := paymentReceived(s, b.CustomerID, b.Month)
690		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
691		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
