694		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
695		if len(b.Lines) == 0 {
696			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
697		} else {
698			fmt.Fprintln(stdout, "明细：")
