707			}
708		}
709		if len(adjs) == 0 {
710			fmt.Fprintln(stdout, "调整与撤销历史：无")
711		} else {
712			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
713			for i, ev := range historyEvents(adjs) {
