720			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
721			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
722				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
723			}
724		}
725	}
