727	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
728	func historyEvents(adjs []*adjustment) []string {
729		type event struct {
730			seq  int64
731			text string
732		}
733		var events []event
734		for _, a := range adjs {
735			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
736				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
737			if a.Revoked {
738				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
739					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
740			}
741		}
742		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
743		out := make([]string, len(events))
744		for i, ev := range events {
745			out[i] = ev.text
746		}
747		return out
748	}
