764	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
765	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
766	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
767	// 的最新分配。
768	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
769		type event struct {
770			seq  int64
771			text string
772		}
773		var events []event
774		for _, p := range pays {
775			alloc := p.amountFor(month)
776			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
777				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
778			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
779			running := alloc
780			for _, c := range correctionsFor(s, p.ID) {
781				after := allocAmountFor(c.Allocations, month)
782				if running == 0 && after == 0 {
783					continue // 本次更正不涉及本账单
784				}
785				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
786					c.ID, c.Reason, p.ID, running, after)})
787				running = after
788			}
789			if p.Revoked {
790				// 整笔撤销取消的是撤销时的最新分配。
791				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
792					p.ID, p.RevokeReason, p.ID, p.Total, running)})
793			}
794			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
795			for _, r := range refundsFor(s, p.ID) {
796				amt := allocAmountFor(r.Allocations, month)
797				if amt <= 0 {
798					continue // 本次退款不涉及本账单
799				}
800				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
801					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
802			}
803		}
804		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
805		out := make([]string, len(events))
806		for i, ev := range events {
807			out[i] = ev.text
808		}
809		return out
810	}
