819	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
820	func parseAmount(text string) (int64, error) {
821		text = strings.TrimSpace(text)
822		amount, err := strconv.ParseInt(text, 10, 64)
823		if err != nil {
824			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
825		}
826		if amount == 0 {
827			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
828		}
829		return amount, nil
830	}
