832	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
833		if !validMonth(month) {
834			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
835		}
836		if strings.TrimSpace(adjID) == "" {
837			return fmt.Errorf("调整标识不能为空")
838		}
839		amount, err := parseAmount(amountText)
840		if err != nil {
841			return err
842		}
843		if strings.TrimSpace(reason) == "" {
844			return fmt.Errorf("调整原因不能为空")
845		}
846	
847		s, err := loadStore(dir)
848		if err != nil {
849			return err
850		}
851		if _, ok := s.Customers[customerID]; !ok {
852			return fmt.Errorf("客户标识 %q 不存在", customerID)
853		}
854		b, ok := s.Bills[billKey(customerID, month)]
855		if !ok {
856			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
857		}
858	
859		if existing, ok := s.Adjustments[adjID]; ok {
860			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
861			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
862			if existing.CustomerID == customerID && existing.Month == month &&
863				existing.Amount == amount && existing.Reason == reason {
864				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
865				printAdjustment(existing, s)
866				return nil
867			}
868			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
869				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
870		}
871	
872		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
873		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
874		// 不占用该调整标识。
875		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
876		if err != nil {
877			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
878		}
879		received, err := paymentReceived(s, customerID, month)
880		if err != nil {
881			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
882		}
883		newPayable, err := addSigned64(payable, amount)
884		if err != nil {
885			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
886		}
887		if newPayable < 0 {
888			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
889		}
890		if newPayable < received {
891			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
892				newPayable, received, payable, amount)
893		}
894	
895		a := &adjustment{
896			ID:         adjID,
897			CustomerID: customerID,
898			Month:      month,
899			Amount:     amount,
900			Reason:     reason,
901			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
902		}
903		s.NextSeq++
904		a.Seq = s.NextSeq
905		s.Adjustments[adjID] = a
906	
907		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
908		// 该调整标识不被占用。
909		if err := s.save(); err != nil {
910			delete(s.Adjustments, adjID)
911			s.NextSeq--
912			return err
913		}
914		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
915			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
916		printAdjustment(a, s)
917		return nil
918	}
