920	func cmdBillRevoke(dir, adjID, reason string) error {
921		if strings.TrimSpace(adjID) == "" {
922			return fmt.Errorf("调整标识不能为空")
923		}
924		if strings.TrimSpace(reason) == "" {
925			return fmt.Errorf("撤销原因不能为空")
926		}
927	
928		s, err := loadStore(dir)
929		if err != nil {
930			return err
931		}
932		a, ok := s.Adjustments[adjID]
933		if !ok {
934			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
935		}
936	
937		if a.Revoked {
938			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
939			// 改用其他原因则拒绝。
940			if a.RevokeReason == reason {
941				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
942				printAdjustment(a, s)
943				return nil
944			}
945			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
946		}
947	
948		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
949		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
950		// 改变余额后重试。
951		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
952		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
953		if err != nil {
954			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
955		}
956		received, err := paymentReceived(s, a.CustomerID, a.Month)
957		if err != nil {
958			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
959		}
960		neg, err := neg64(a.Amount)
961		if err != nil {
962			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
963		}
964		newPayable, err := addSigned64(payable, neg)
965		if err != nil {
966			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
967				payable, a.Amount)
968		}
969		if newPayable < 0 {
970			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
971				newPayable, payable, a.Amount)
972		}
973		if newPayable < received {
974			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
975				newPayable, received, payable, a.Amount)
976		}
977	
978		a.Revoked = true
979		a.RevokeReason = reason
980		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
981		s.NextSeq++
982		a.RevokeSeq = s.NextSeq
983	
984		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
985		if err := s.save(); err != nil {
986			a.Revoked = false
987			a.RevokeReason = ""
988			a.RevokedAt = ""
989			a.RevokeSeq = 0
990			s.NextSeq--
991			return err
992		}
993		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
994			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
995		printAdjustment(a, s)
996		return nil
997	}
