1000	func printAdjustment(a *adjustment, s *state) {
1001		b := s.Bills[billKey(a.CustomerID, a.Month)]
1002		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
1003		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
1004		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
1005		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
1006		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
1007		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
1008		if a.Revoked {
1009			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
1010		} else {
1011			fmt.Fprintf(stdout, "当前状态：生效中\n")
1012		}
1013		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
1014	}
