1020		if err != nil {
1021			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1022		}
1023		if amount <= 0 {
1024			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1025		}
1026		return amount, nil
1027	}
