1042	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1043		total, err := parsePositiveAmount(totalText)
1044		if err != nil {
1045			return err
1046		}
1047		allocs, err := parseAllocations(allocArgs)
1048		if err != nil {
1049			return err
1050		}
1051		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1052		var sum int64
1053		for _, al := range allocs {
1054			sum, err = add64(sum, al.Amount)
1055			if err != nil {
1056				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1057			}
1058		}
1059		if sum != total {
1060			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1061		}
1062		return registerPayment(dir, customerID, payID, total, note, allocs)
1063	}
1064	
1065	// --- 自动分配汇款（bill remit-auto） ---
1066	
1067	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1068	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1069	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1070	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1071	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1072	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1073		total, err := parsePositiveAmount(totalText)
1074		if err != nil {
1075			return err
1076		}
1077		if strings.TrimSpace(payID) == "" {
1078			return fmt.Errorf("收款标识不能为空")
1079		}
1080		if strings.TrimSpace(note) == "" {
1081			return fmt.Errorf("收款备注不能为空")
1082		}
1083	
1084		s, err := loadStore(dir)
1085		if err != nil {
1086			return err
1087		}
1088		if _, ok := s.Customers[customerID]; !ok {
1089			return fmt.Errorf("客户标识 %q 不存在", customerID)
1090		}
1091	
1092		if existing, ok := s.Payments[payID]; ok {
1093			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1094			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1095			// 不恢复旧分配或已退、已撤销金额。
1096			if existing.Auto && existing.CustomerID == customerID &&
1097				existing.Total == total && existing.Note == note {
1098				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1099				printAutoPayment(s, existing)
1100				return nil
1101			}
1102			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1103			if !existing.Auto {
1104				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1105					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1106			}
1107			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1108				payID, existing.CustomerID, existing.Total, existing.Note)
1109		}
1110	
1111		// 首次登记：归集该客户当前已有账单的月份，按 UTC 账期月升序排列
1112		// （YYYY-MM 字典序即时间序）。不补结算，只有已存在账单参与分配。
1113		var months []string
1114		for _, b := range s.Bills {
1115			if b.CustomerID == customerID {
1116				months = append(months, b.Month)
1117			}
1118		}
1119		sort.Strings(months)
1120	
1121		// 依次偿还当前未收余额：跳过余额为 0 的月份，前一月份还清后才分配
1122		// 下一月，最后一月可部分偿还。每月未收余额 = 当前应付 − 实收，均在
1123		// [0, 有符号 64 位最大值] 内；remaining 从总额（正整数分）起只减不增，
1124		// 各月余额与分配全程整数计算——即使全部账单欠款合计超过 64 位上限，
1125		// 分配过程也只涉及不超过总额的中间值，不会误拒合法金额。
1126		remaining := total
1127		var allocs []paymentAllocation
1128		for _, m := range months {
1129			if remaining == 0 {
1130				break
1131			}
1132			b := s.Bills[billKey(customerID, m)]
1133			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, m))
1134			if err != nil {
1135				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, m, err)
1136			}
1137			received, err := paymentReceived(s, customerID, m)
1138			if err != nil {
1139				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, m, err)
1140			}
1141			outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
1142			if outstanding <= 0 {
1143				continue // 跳过余额为 0 的月份
1144			}
1145			amt := outstanding
1146			if amt > remaining {
1147				amt = remaining // 最后一月可部分偿还
1148			}
1149			allocs = append(allocs, paymentAllocation{Month: m, Amount: amt})
1150			remaining -= amt
1151		}
1152		if len(allocs) == 0 {
1153			return fmt.Errorf("客户 %s 当前没有欠款（全部已存在账单的未收余额均为 0），整笔拒绝；不补结算、不跨客户、不留未分配款项", customerID)
1154		}
1155		if remaining > 0 {
1156			return fmt.Errorf("收款总额 %d 分超过客户 %s 全部已存在账单的欠款合计 %d 分，整笔拒绝；不补结算、不跨客户、不留未分配款项",
1157				total, customerID, total-remaining)
1158		}
1159	
1160		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1161		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1162		// 固定分配的规则。
1163		p := &payment{
1164			ID:          payID,
1165			CustomerID:  customerID,
1166			Total:       total,
1167			Note:        note,
1168			Allocations: allocs,
1169			Auto:        true,
1170			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1171		}
1172		s.NextSeq++
1173		p.Seq = s.NextSeq
1174		s.Payments[payID] = p
1175	
1176		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1177		// 不生效，该收款标识与序号不被占用，可原样重试。
1178		if err := s.save(); err != nil {
1179			delete(s.Payments, payID)
1180			s.NextSeq--
1181			return err
1182		}
1183		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1184			payID, total, moneyFen(total))
1185		printAutoPayment(s, p)
1186		return nil
1187	}
1188	
1189	// printAutoPayment 输出一笔自动分配登记的收款：收款标识、总额、备注、当前
1190	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1191	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1192	func printAutoPayment(s *state, p *payment) {
1193		current := currentAllocations(s, p)
1194		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1195		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1196		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1197		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1198		if p.Revoked {
1199			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1200		} else {
1201			fmt.Fprintf(stdout, "当前状态：实收中\n")
1202		}
1203		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1204		if sameAllocations(current, p.Allocations) {
1205			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1206		} else {
1207			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1208		}
1209		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1210		for _, m := range unionMonths(p.Allocations, current) {
1211			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1212			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1213			received, _ := paymentReceived(s, p.CustomerID, m)
1214			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1215				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1216				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1217		}
1218	}
1219	
1220	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1221	// 月份不得重复，每项金额为正整数分。
1222	func parseAllocations(args []string) ([]paymentAllocation, error) {
1223		if len(args) == 0 {
1224			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1225		}
1226		seen := make(map[string]bool)
1227		allocs := make([]paymentAllocation, 0, len(args))
1228		for _, arg := range args {
1229			parts := strings.Split(arg, ":")
1230			if len(parts) != 2 {
1231				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1232			}
1233			month := strings.TrimSpace(parts[0])
1234			if !validMonth(month) {
1235				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1236			}
1237			if seen[month] {
1238				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1239			}
1240			seen[month] = true
1241			amount, err := parsePositiveAmount(parts[1])
1242			if err != nil {
1243				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1244			}
1245			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1246		}
1247		return allocs, nil
1248	}
1249	
1250	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1251	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1252	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1253		if strings.TrimSpace(payID) == "" {
1254			return fmt.Errorf("收款标识不能为空")
1255		}
1256		if strings.TrimSpace(note) == "" {
1257			return fmt.Errorf("收款备注不能为空")
1258		}
1259		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1260		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1261	
1262		s, err := loadStore(dir)
1263		if err != nil {
1264			return err
1265		}
1266		if _, ok := s.Customers[customerID]; !ok {
1267			return fmt.Errorf("客户标识 %q 不存在", customerID)
1268		}
1269		for _, al := range allocs {
1270			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1271				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1272			}
1273		}
1274	
1275		if existing, ok := s.Payments[payID]; ok {
1276			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1277			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1278			if existing.Auto {
1279				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1280					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1281			}
1282			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1283			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1284			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1285			if samePaymentContent(existing, customerID, total, note, allocs) {
1286				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1287				printPayment(existing, s)
1288				return nil
1289			}
1290			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1291				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1292		}
1293	
1294		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1295		for _, al := range allocs {
1296			b := s.Bills[billKey(customerID, al.Month)]
1297			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1298			if err != nil {
1299				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1300			}
1301			received, err := paymentReceived(s, customerID, al.Month)
1302			if err != nil {
1303				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1304			}
1305			if payable == 0 {
1306				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1307			}
1308			if al.Amount > payable-received {
1309				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1310					al.Amount, payable-received, customerID, al.Month, payable, received)
1311			}
1312		}
1313	
1314		p := &payment{
1315			ID:          payID,
1316			CustomerID:  customerID,
1317			Total:       total,
1318			Note:        note,
1319			Allocations: allocs,
1320			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1321		}
1322		s.NextSeq++
1323		p.Seq = s.NextSeq
1324		s.Payments[payID] = p
1325	
1326		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1327		// 一切不生效，该收款标识不被占用。
1328		if err := s.save(); err != nil {
1329			delete(s.Payments, payID)
1330			s.NextSeq--
1331			return err
1332		}
1333		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1334		printAllocationBalances(s, p, allocs)
1335		fmt.Fprintln(stdout)
1336		printPayment(p, s)
1337		return nil
1338	}
1339	
1340	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1341	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1342	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1343		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1344			return false
1345		}
1346		return sameAllocations(p.Allocations, allocs)
1347	}
1348	
1349	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1350	func sameAllocations(a, b []paymentAllocation) bool {
1351		if len(a) != len(b) {
1352			return false
1353		}
1354		for _, al := range b {
1355			if allocAmountFor(a, al.Month) != al.Amount {
1356				return false
1357			}
1358		}
1359		return true
1360	}
1361	
1362	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1363	func formatAllocations(allocs []paymentAllocation) string {
1364		parts := make([]string, len(allocs))
1365		for i, al := range allocs {
1366			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1367		}
1368		return strings.Join(parts, ",")
1369	}
1370	
1371	// printAllocationBalances 输出给定分配列表每个分配月份当前的实收与未收余额。
1372	func printAllocationBalances(s *state, p *payment, allocs []paymentAllocation) {
1373		for _, al := range allocs {
1374			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1375			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1376			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1377			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
1378				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
1379		}
1380	}
1381	
1382	func cmdBillUnpay(dir, payID, reason string) error {
1383		if strings.TrimSpace(payID) == "" {
1384			return fmt.Errorf("收款标识不能为空")
1385		}
1386		if strings.TrimSpace(reason) == "" {
1387			return fmt.Errorf("撤销原因不能为空")
1388		}
1389	
1390		s, err := loadStore(dir)
1391		if err != nil {
1392			return err
1393		}
1394		p, ok := s.Payments[payID]
1395		if !ok {
1396			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1397		}
1398	
1399		if p.Revoked {
1400			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1401			// 改用其他原因则拒绝。
1402			if p.RevokeReason == reason {
1403				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1404				printPayment(p, s)
1405				return nil
1406			}
1407			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1408		}
1409	
1410		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1411		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1412		// 处理。
1413		if paymentHasRefunds(s, payID) {
1414			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1415		}
1416	
1417		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1418		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1419		// 分配、更正与撤销原因永久保留。
1420		p.Revoked = true
1421		p.RevokeReason = reason
1422		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1423		s.NextSeq++
1424		p.RevokeSeq = s.NextSeq
1425	
1426		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1427		if err := s.save(); err != nil {
1428			p.Revoked = false
1429			p.RevokeReason = ""
1430			p.RevokedAt = ""
1431			p.RevokeSeq = 0
1432			s.NextSeq--
1433			return err
1434		}
1435		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1436		printAllocationBalances(s, p, currentAllocations(s, p))
1437		fmt.Fprintln(stdout)
1438		printPayment(p, s)
1439		return nil
1440	}
