1442	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1443	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1444	// 各月应付/实收取自当前库状态。
1445	func printPayment(p *payment, s *state) {
1446		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1447		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1448		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1449		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1450		if p.Revoked {
1451			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1452		} else {
1453			fmt.Fprintf(stdout, "当前状态：实收中\n")
1454		}
1455		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1456		for i, al := range p.Allocations {
1457			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1458			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1459			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1460			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1461				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1462		}
1463		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1464			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1465				len(corrs), formatAllocations(currentAllocations(s, p)))
1466		}
1467		if refs := refundsFor(s, p.ID); len(refs) > 0 {
1468			current := currentAllocations(s, p)
1469			fmt.Fprintf(stdout, "退款记录（%d 笔，永久保留、不可撤销；首次退款后最新分配已固定）：\n", len(refs))
1470			for _, r := range refs {
1471				fmt.Fprintf(stdout, "  退款 %s：%s，原因：%s\n", r.ID, formatAllocations(r.Allocations), r.Reason)
1472			}
1473			fmt.Fprintln(stdout, "各月剩余可退额（最新分配减累计退款）：")
1474			for _, al := range current {
1475				refunded := refundedForMonth(s, p.ID, al.Month)
1476				fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，累计已退 %d 分，剩余可退 %d 分（%s）\n",
1477					al.Month, al.Amount, refunded, al.Amount-refunded, moneyFen(al.Amount-refunded))
1478			}
1479		}
1480	}
