1482	// --- 收款分配更正 ---
1483	
1484	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1485		if strings.TrimSpace(payID) == "" {
1486			return fmt.Errorf("收款标识不能为空")
1487		}
1488		if strings.TrimSpace(corrID) == "" {
1489			return fmt.Errorf("更正标识不能为空")
1490		}
1491		if strings.TrimSpace(reason) == "" {
1492			return fmt.Errorf("更正原因不能为空")
1493		}
1494		allocs, err := parseAllocations(allocArgs)
1495		if err != nil {
1496			return err
1497		}
1498		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1499		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1500	
1501		s, err := loadStore(dir)
1502		if err != nil {
1503			return err
1504		}
1505		p, ok := s.Payments[payID]
1506		if !ok {
1507			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1508		}
1509	
1510		if existing, ok := s.Corrections[corrID]; ok {
1511			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1512			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1513			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1514			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1515				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1516				printCorrection(existing, s)
1517				return nil
1518			}
1519			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1520				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1521		}
1522	
1523		// 新增更正只允许未撤销收款。
1524		if p.Revoked {
1525			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1526		}
1527	
1528		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1529		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1530		if paymentHasRefunds(s, payID) {
1531			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1532		}
1533	
1534		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1535		var sum int64
1536		for _, al := range allocs {
1537			sum, err = add64(sum, al.Amount)
1538			if err != nil {
1539				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1540			}
1541		}
1542		if sum != p.Total {
1543			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1544		}
1545		// 新分配月份须是原客户的已结算账单。
1546		for _, al := range allocs {
1547			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1548				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1549			}
1550		}
1551	
1552		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1553		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1554		current := currentAllocations(s, p)
1555		for _, m := range unionMonths(current, allocs) {
1556			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1557			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1558			if err != nil {
1559				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1560			}
1561			received, err := paymentReceived(s, p.CustomerID, m)
1562			if err != nil {
1563				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1564			}
1565			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1566			received -= allocAmountFor(current, m)
1567			received, err = add64(received, allocAmountFor(allocs, m))
1568			if err != nil {
1569				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1570			}
1571			if received > payable {
1572				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1573					p.CustomerID, m, received, payable)
1574			}
1575		}
1576	
1577		c := &correction{
1578			ID:          corrID,
1579			PaymentID:   payID,
1580			Reason:      reason,
1581			Allocations: allocs,
1582			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1583		}
1584		s.NextSeq++
1585		c.Seq = s.NextSeq
1586		s.Corrections[corrID] = c
1587	
1588		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1589		// 一切不生效，该更正标识不被占用。
1590		if err := s.save(); err != nil {
1591			delete(s.Corrections, corrID)
1592			s.NextSeq--
1593			return err
1594		}
1595		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1596		printCorrection(c, s)
1597		return nil
1598	}
1599	
1600	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1601	func unionMonths(a, b []paymentAllocation) []string {
1602		set := make(map[string]bool, len(a)+len(b))
1603		for _, al := range a {
1604			set[al.Month] = true
1605		}
1606		for _, al := range b {
1607			set[al.Month] = true
1608		}
1609		months := make([]string, 0, len(set))
1610		for m := range set {
1611			months = append(months, m)
1612		}
1613		sort.Strings(months)
1614		return months
1615	}
1616	
1617	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1618	// 新分配，或（首次更正时）收款的原始分配。
1619	func allocationBefore(s *state, c *correction) []paymentAllocation {
1620		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1621		var latest *correction
1622		for _, o := range s.Corrections {
1623			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1624				latest = o
1625			}
1626		}
1627		if latest != nil {
1628			before = latest.Allocations
1629		}
1630		return before
1631	}
