1655	// --- 账后对账流水 ---
1656	
1657	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1658	// 分配更正、撤销收款或退款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1659	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1660	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值；退款在其发生
1661	// 序号减少本账单实收，不可撤销。
1662	type ledgerEvent struct {
1663		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1664		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
1665		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1666		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1667		deltaReceived int64  // 对实收的影响（分，带符号）
1668		note          string // 原因（调整/更正类）或备注（收款类）
1669		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1670		payTotal      int64  // 收款类事件：汇款总额
1671		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1672		payID         string // 更正/退款事件：关联收款标识
1673		beforeAlloc   int64  // 更正事件：本账单更正前分配
1674		afterAlloc    int64  // 更正事件：本账单更正后分配
1675		afterPayable  int64  // 事件后的应付（回放时填充）
1676		afterReceived int64  // 事件后的实收（回放时填充）
1677	}
1678	
1679	// billLedger 返回目标账单的一条按操作序号升序的账后流水，事件之后的三项
1680	// 余额已逐步填充。业务归属、金额影响（调整/撤销/收款/更正/撤销收款/退款）
1681	// 与完整性核验都来自与 bill reconcile 共用的 postbill 计算，本处只取该账单
1682	// 那一条流水：
1683	//
1684	//   - 以原总金额为初始应付、零实收为起点；
1685	//   - 回放覆盖完整流水（不受查询截止序号限制），序号重复、撤销先于原操作，
1686	//     或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值，都视为
1687	//     数据异常并拒绝，即使异常发生在截止序号之后——只检查最终余额会放过
1688	//     中间越界的存档；
1689	//   - 曾涉及该账单的收款在被更正移出该月后，仍保留零金额撤销事件。
1690	//
1691	// 只读：不修改库、不占用序号、不新增记录。
1692	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1693		ops, err := postbillOps(s, b.CustomerID)
1694		if err != nil {
1695			return nil, err
1696		}
1697		ledgers, err := verifyPostbillLedgers(ops, []*bill{b})
1698		if err != nil {
1699			return nil, err
1700		}
1701		return ledgers[b.Month], nil
1702	}
1703	
1704	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1705		if !validMonth(month) {
1706			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1707		}
1708		s, err := loadStore(dir)
1709		if err != nil {
1710			return err
1711		}
1712		cust, ok := s.Customers[customerID]
1713		if !ok {
1714			return fmt.Errorf("客户标识 %q 不存在", customerID)
1715		}
1716		b, ok := s.Bills[billKey(customerID, month)]
1717		if !ok {
1718			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1719		}
1720	
1721		// 截止序号使用调整/收款/更正/退款及其撤销共用的已保存全局序号：省略表示最新，
1722		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1723		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1724		cutoff := s.NextSeq
1725		cutoffDesc := "省略，按最新"
1726		if hasCutoff {
1727			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1728			if perr != nil {
1729				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1730			}
1731			if v < 0 {
1732				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1733			}
1734			if v > s.NextSeq {
1735				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1736			}
1737			cutoff = v
1738			cutoffDesc = "指定"
1739		}
1740	
1741		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1742		// 拒绝，不输出部分正常的报告。
1743		events, err := billLedger(s, b)
1744		if err != nil {
1745			return err
1746		}
1747		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1748		return nil
1749	}
1750	
1751	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1752		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1753		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1754		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1755		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1756		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1757		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1758		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1759			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1760	
1761		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1762		payable, received := b.TotalFee, int64(0)
1763		var shown []ledgerEvent
1764		for _, ev := range events {
1765			if ev.seq > cutoff {
1766				continue
1767			}
1768			shown = append(shown, ev)
1769			payable, received = ev.afterPayable, ev.afterReceived
1770		}
1771		if len(shown) == 0 {
1772			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1773		} else {
1774			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1775			for i, ev := range shown {
1776				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1777			}
1778		}
1779		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1780			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1781	}
1782	
1783	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1784	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1785	// 说明汇款总额与本账单分配。
1786	func formatLedgerEvent(ev ledgerEvent) string {
1787		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1788			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1789		switch ev.kind {
1790		case "调整":
1791			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1792				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1793		case "撤销调整":
1794			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1795				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1796		case "收款":
1797			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1798				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1799		case "更正":
1800			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1801				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1802		case "退款":
1803			return fmt.Sprintf("序号 %d 退款 %s：实收 %+d 分（%s，关联收款 %s，本账单退款 %d 分），原因：%s → %s",
1804				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.payAlloc, ev.note, after)
1805		default: // 撤销收款
1806			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1807				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1808		}
1809	}
1810

