79		}
80		// 已撤回（含被其他更正替代，该项已在上面按重放处理）的记录不能再更正；
81		// 更正只能作用于一条仍有效的原记录。
82		if s.isWithdrawn(origID) {
83			w := s.Withdrawals[origID]
