1	package main
2	
3	import (
4		"errors"
5		"os"
6		"strings"
7		"testing"
8	)
9	
10	// --- 按月暂停区间测试 ---
11	
12	func TestSuspensionRegisterHappyPathAndQuery(t *testing.T) {
13		h := newHarness(t)
14		h.mustRun("plan", "add-fee", "sub", "订阅阶梯", "1000", "100:10", "-:5")
15		h.mustRun("customer", "add-plan", "c1", "客户一", "sub")
16	
17		out := h.mustRun("customer", "suspend", "c1", "2026-11", "2027-02", "店面装修暂停营业")
18		for _, want := range []string{
19			"已登记暂停区间", "客户：c1", "暂停区间：2026-11（含）至 2027-02（不含", "原因：店面装修暂停营业",
20		} {
21			if !strings.Contains(out, want) {
22				t.Fatalf("登记暂停输出缺少 %q:\n%s", want, out)
23			}
24		}
25	
26		// 查询全部区间：按起月升序展示区间与原因。
27		out = h.mustRun("customer", "suspensions", "c1")
28		for _, want := range []string{
29			"客户：c1（客户一）", "暂停区间（按起月升序",
30			"2026-11（含）至 2027-02（不含）", "原因：店面装修暂停营业",
31		} {
32			if !strings.Contains(out, want) {
33				t.Fatalf("暂停查询输出缺少 %q:\n%s", want, out)
34			}
35		}
36	
37		// 指定月份：起月含、结束月不含，区间外正常服务。
38		cases := map[string]bool{
39			"2026-10": false, // 区间之前
40			"2026-11": true,  // 起月（含）
41			"2026-12": true,
42			"2027-01": true,
43			"2027-02": false, // 结束月（不含）= 恢复服务
44		}
45		for month, suspended := range cases {
46			out = h.mustRun("customer", "suspensions", "c1", month)
47			got := strings.Contains(out, "已暂停")
48			if got != suspended {
49				t.Fatalf("月份 %s 暂停状态=%v，期望 %v:\n%s", month, got, suspended, out)
50			}
51		}
52	}
53	
54	func TestSuspensionValidation(t *testing.T) {
55		h := newHarness(t)
56		h.mustRun("plan", "add", "p1", "阶梯", "-:10")
57		h.mustRun("customer", "add-plan", "c1", "客户一", "p1")
58		h.mustRun("customer", "add", "c9", "固定客户", "10")
59	
60		h.runExpectErr("customer", "suspend", "c1", "2026-13", "2027-01", "原因") // 起月非法
61		h.runExpectErr("customer", "suspend", "c1", "2026-11", "2026-1", "原因")  // 结束月格式错
62		h.runExpectErr("customer", "suspend", "c1", "2026-11", "2026-11", "原因") // 结束月=起月
63		h.runExpectErr("customer", "suspend", "c1", "2026-11", "2026-10", "原因") // 结束月早于起月
64		h.runExpectErr("customer", "suspend", "c1", "2026-11", "2027-01", "  ") // 空原因
65		h.runExpectErr("customer", "suspend", "ghost", "2026-11", "2027-01", "原因")
66		// 仅限已绑定阶梯方案的客户。
67		if msg := h.runExpectErr("customer", "suspend", "c9", "2026-11", "2027-01", "原因"); !strings.Contains(msg, "固定单价") {
68			t.Fatal(msg)
69		}
70		// 参数数量错误是用法错误（退出码 2）；月份非法由命令返回业务错误（退出码 1）。
71		for _, args := range [][]string{
72			{"customer", "suspend", "c1", "2026-11", "2027-01"},
73			{"customer", "suspend", "c1", "2026-11"},
74			{"customer", "suspensions"},
75		} {
76			_, err := h.run(args...)
77			var ue usageErrorf
78			if !errors.As(err, &ue) {
79				t.Fatalf("args=%v 应为用法错误(2)，得到 %v", args, err)
80			}
81		}
82		h.runExpectErr("customer", "suspensions", "c1", "2026-13")
83		// 查询固定单价客户：说明不适用暂停（含/不含月份两种形式）。
84		if out := h.mustRun("customer", "suspensions", "c9"); !strings.Contains(out, "不适用按月暂停") {
85			t.Fatalf("固定客户查询异常:\n%s", out)
86		}
87		if out := h.mustRun("customer", "suspensions", "c9", "2026-11"); !strings.Contains(out, "不适用暂停") {
88			t.Fatalf("固定客户按月查询异常:\n%s", out)
89		}
90		// 查询不存在的客户失败但不改写存档。
91		h.runExpectErr("customer", "suspensions", "ghost")
92		// 全部失败后起月未被占用，可原样登记成功。
93		h.mustRun("customer", "suspend", "c1", "2026-11", "2027-01", "首次暂停")
94	}
95	
96	func TestSuspensionIdempotentReplayAndImmutable(t *testing.T) {
97		h := newHarness(t)
98		h.mustRun("plan", "add-fee", "sub", "订阅阶梯", "1000", "-:10")
99		h.mustRun("customer", "add-plan", "c1", "客户一", "sub")
100		h.mustRun("customer", "suspend", "c1", "2026-11", "2027-01", "装修")
101	
102		before, err := os.ReadFile(h.statePath())
103		if err != nil {
104			t.Fatal(err)
105		}
106		// 相同结束月与原因的重放返回原记录且不写盘。
107		out := h.mustRun("customer", "suspend", "c1", "2026-11", "2027-01", "装修")
108		if !strings.Contains(out, "内容相同，返回原记录") {
109			t.Fatalf("重放未幂等返回:\n%s", out)
110		}
111		after, err := os.ReadFile(h.statePath())
112		if err != nil {
113			t.Fatal(err)
114		}
