405		h.mustRun("customer", "add-plan", "c1", "客户一", "p1")
406		h.mustRun("customer", "suspend", "c1", "2026-11", "2026-12", "第一段")
407		h.mustRun("customer", "suspend", "c1", "2026-12", "2027-01", "第二段相接")
408	
409		good, err := os.ReadFile(h.statePath())
410		if err != nil {
411			t.Fatal(err)
412		}
413		cases := []struct {
414			name string
415			old  string
416			new  string
417		}{
418			{
419				"引用失效客户",
420				"\"c1|2026-11\": {\n      \"customer_id\": \"c1\"",
421				"\"c1|2026-11\": {\n      \"customer_id\": \"ghost\"",
422			},
423			{
424				"非法区间（结束月不晚于起月）",
425				`"start_month": "2026-11",
426	      "end_month": "2026-12"`,
427				`"start_month": "2026-11",
428	      "end_month": "2026-11"`,
429			},
430			{
431				"同客户区间重叠（相接改包围）",
432				`"end_month": "2026-12",
433	      "reason": "第一段"`,
434				`"end_month": "2027-01",
435	      "reason": "第一段"`,
436			},
437		}
438		for _, tc := range cases {
439			broken := strings.Replace(string(good), tc.old, tc.new, 1)
440			if broken == string(good) {
441				t.Fatalf("%s：替换未生效", tc.name)
442			}
443			if err := os.WriteFile(h.statePath(), []byte(broken), 0o644); err != nil {
444				t.Fatal(err)
