447			if !strings.Contains(msg, "损坏") {
448				t.Fatalf("%s：未报损坏: %s", tc.name, msg)
449			}
450			got, _ := os.ReadFile(h.statePath())
451			if string(got) != broken {
452				t.Fatalf("%s：损坏文件被改写", tc.name)
453			}
454		}
