				i+1, su.StartMonth, su.EndMonth, su.Reason)
		}
	}
	if hasMonth {
		var hit *suspension
		for _, su := range list {
			if monthInRange(month, su.StartMonth, su.EndMonth) {
				hit = su
				break
			}
		}
		if hit != nil {
			fmt.Fprintf(stdout, "月份 %s：已暂停（处于区间 %s（含）至 %s（不含）），原因：%s\n",
				month, hit.StartMonth, hit.EndMonth, hit.Reason)
