// resumeCorruptBase 构造用于载入损坏测试的最小数据文件内容。
func resumeCorruptBase(suspensions, resumes, usage, bills string) string {
	return `{
  "version": 1,
  "customers": {"c1": {"id": "c1", "name": "甲方", "price_fen": 0, "plan_id": "p1"}},
