123			if !strings.Contains(out, want) {
124				t.Fatalf("恢复重放输出缺少 %q:\n%s", want, out)
125			}
126		}
127		after, err := os.ReadFile(h.statePath())
128		if err != nil {
129			t.Fatal(err)
130		}
131		if string(after) != string(before) {
132			t.Fatal("相同恢复重放改写了存档")
133		}
134		// 恢复月不同 / 原因不同均拒绝，恢复记录不可改写。
135		h.runExpectErr("customer", "resume", "c1", "2026-11", "2027-02", "提前复业")
136		h.runExpectErr("customer", "resume", "c1", "2026-11", "2027-01", "其他原因")
137	
138		// 后续封账、方案变更、新增暂停都不阻止相同重放，也不撤销后来的暂停。
139		f := h.writeFile("u.csv", csvHeader+"u1,c1,2027-01-05T00:00:00Z,60\n")
