143		h.mustRun("customer", "suspend", "c1", "2027-02", "2027-03", "释放月又暂停")
144		out = h.mustRun("customer", "resume", "c1", "2026-11", "2027-01", "提前复业")
145		if !strings.Contains(out, "内容相同，返回保存信息与当前有效区间") {
